ADMIN_PAGE = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Nexus 管理中心</title>
<style>
:root{--bg:#f3f7f6;--surface:#fff;--surface2:#edf4f2;--ink:#203d41;--muted:#718286;--line:#d9e5e2;--mint:#356a68;--mint2:#dcebe7;--danger:#a84840;--shadow:0 12px 36px rgba(36,71,70,.08)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.55 "Microsoft YaHei",system-ui,sans-serif}.hidden{display:none!important}button,input,textarea{font:inherit}.login{min-height:100vh;display:grid;place-items:center;padding:24px}.login-card{width:min(390px,100%);background:#fff;border:1px solid var(--line);border-radius:24px;padding:30px;box-shadow:var(--shadow)}h1,h2,p{margin-top:0}.sub,.muted{color:var(--muted)}.field{display:block;margin:14px 0}.field span{display:block;margin-bottom:6px;color:var(--muted)}input,textarea{width:100%;border:1px solid var(--line);border-radius:12px;background:#fff;padding:11px 13px;outline:none;color:var(--ink)}input:focus,textarea:focus{border-color:#78a6a1;box-shadow:0 0 0 3px #dcebe8}.button{border:0;border-radius:12px;padding:10px 15px;background:var(--mint);color:#fff;cursor:pointer}.button.secondary{background:var(--mint2);color:var(--mint)}.button.danger{background:#f7e7e5;color:var(--danger)}.button:disabled{opacity:.55;cursor:not-allowed}.error{color:var(--danger);min-height:22px;margin-top:10px}.shell{height:100vh;display:grid;grid-template-columns:216px minmax(0,1fr)}.sidebar{background:#eaf2f0;border-right:1px solid var(--line);padding:24px 15px}.brand{font-size:23px;font-weight:750;padding:0 10px}.brand small{display:block;font-size:12px;font-weight:500;color:var(--muted)}.navs{display:grid;gap:5px;margin-top:26px}.nav{border:0;background:transparent;color:var(--ink);text-align:left;border-radius:11px;padding:11px 13px;cursor:pointer}.nav.active{background:#fff;color:var(--mint);font-weight:700;box-shadow:0 5px 18px rgba(36,71,70,.07)}.main{min-width:0;overflow:auto;padding:26px 32px}.page-head{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:20px}.page-head h1{font-size:25px;margin-bottom:2px}.section{display:none}.section.active{display:block}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.metric,.panel{background:#fff;border:1px solid var(--line);border-radius:17px;box-shadow:var(--shadow)}.metric{padding:18px}.metric b{display:block;font-size:25px;margin-top:6px}.panel-title{padding:15px 17px;border-bottom:1px solid var(--line);font-weight:700}.status-list{padding:4px 17px}.status-row{display:flex;justify-content:space-between;gap:20px;padding:13px 0;border-bottom:1px solid #edf2f1}.toolbar{display:flex;gap:10px;margin-bottom:13px}.toolbar input{max-width:430px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px 15px;border-bottom:1px solid #edf2f1;white-space:nowrap}th{font-size:12px;color:var(--muted);background:#fafcfc}.empty{padding:50px;text-align:center;color:var(--muted)}.chat-layout{display:grid;grid-template-columns:270px minmax(0,1fr);height:calc(100vh - 105px);background:#fff;border:1px solid var(--line);border-radius:18px;overflow:hidden;box-shadow:var(--shadow)}.conversation-list{border-right:1px solid var(--line);display:flex;flex-direction:column;min-height:0}.conversation-head{padding:13px;border-bottom:1px solid var(--line);display:flex;gap:8px}.conversation-head input{min-width:0}.conversation-rows{overflow:auto}.conversation{padding:12px 14px;border-bottom:1px solid #edf2f1;cursor:pointer}.conversation:hover,.conversation.active{background:#eef6f4}.conversation b{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.chat-pane{display:flex;flex-direction:column;min-width:0}.chat-title{padding:14px 18px;border-bottom:1px solid var(--line);font-weight:700}.messages{flex:1;overflow:auto;padding:20px;display:flex;flex-direction:column;gap:11px;background:#f8fbfa}.message{max-width:80%;padding:10px 13px;border-radius:15px;background:#fff;border:1px solid var(--line);white-space:pre-wrap;word-break:break-word}.message.user{align-self:flex-end;background:#deece9;border-color:#d0e2de}.message.assistant{align-self:flex-start}.composer{border-top:1px solid var(--line);padding:12px;display:flex;gap:10px;align-items:flex-end}.composer textarea{resize:none;min-height:44px;max-height:128px}.account-card{max-width:620px;padding:22px}.notice{padding:11px 13px;border-radius:12px;background:#edf5f3;color:var(--mint);margin-bottom:14px}.success{color:#32745d;min-height:22px;margin-top:10px}@media(max-width:800px){.shell{grid-template-columns:1fr;height:auto;min-height:100vh}.sidebar{padding:13px;border-right:0;border-bottom:1px solid var(--line)}.brand small{display:none}.navs{display:flex;overflow:auto;margin-top:10px}.nav{white-space:nowrap}.main{padding:18px 12px}.grid{grid-template-columns:1fr 1fr}.chat-layout{grid-template-columns:1fr;height:auto}.conversation-list{height:240px;border-right:0;border-bottom:1px solid var(--line)}.chat-pane{height:620px}.page-head{align-items:flex-start}.message{max-width:92%}}
</style></head><body>
<section id="loginPage" class="login"><form class="login-card" onsubmit="signIn(event)"><h1>Nexus 管理中心</h1><p class="sub">网页聊天、文件管理和账号安全</p><label class="field"><span>账号</span><input id="username" autocomplete="username" required></label><label class="field"><span>密码</span><input id="password" type="password" autocomplete="current-password" required></label><button class="button" style="width:100%">登录</button><div id="loginError" class="error"></div></form></section>
<section id="appPage" class="shell hidden"><aside class="sidebar"><div class="brand">Nexus<small>移动管理中心</small></div><nav class="navs"><button class="nav active" data-page="overview" onclick="showPage('overview')">概览</button><button class="nav" data-page="chat" onclick="showPage('chat')">网页聊天</button><button class="nav" data-page="files" onclick="showPage('files')">文件管理</button><button class="nav" data-page="audio" onclick="showPage('audio')">语音管理</button><button class="nav" data-page="account" onclick="showPage('account')">账号安全</button><button class="nav" data-page="system" onclick="showPage('system')">系统状态</button></nav></aside><main class="main"><header class="page-head"><div><h1 id="pageTitle">概览</h1><p id="pageDesc" class="sub">Nexus运行概况</p></div><button class="button secondary" onclick="logout()">退出</button></header>
<section id="overview" class="section active"><div class="grid"><div class="metric"><span class="muted">对话</span><b id="metricSessions">—</b></div><div class="metric"><span class="muted">文件</span><b id="metricFiles">—</b></div><div class="metric"><span class="muted">语音</span><b id="metricAudio">—</b></div><div class="metric"><span class="muted">总空间</span><b id="metricBytes">—</b></div></div><div class="panel" style="margin-top:14px"><div class="panel-title">连接状态</div><div class="status-list"><div class="status-row"><span>移动网关</span><span id="gatewayStatus">检查中</span></div><div class="status-row"><span>Hermes 核心</span><span id="hermesStatus">检查中</span></div><div class="status-row"><span>当前入口</span><span id="entryAddress"></span></div></div></div></section>
<section id="chat" class="section"><div class="chat-layout"><div class="conversation-list"><div class="conversation-head"><input id="sessionSearch" placeholder="搜索对话" oninput="renderSessions()"><button class="button secondary" onclick="loadSessions()">刷新</button></div><div id="sessionRows" class="conversation-rows"></div></div><div class="chat-pane"><div id="chatTitle" class="chat-title">选择一个对话</div><div id="messages" class="messages"><div class="empty">从左侧选择对话后即可查看和发送消息</div></div><form class="composer" onsubmit="sendChat(event)"><textarea id="chatInput" placeholder="和Nexus说点什么……" disabled></textarea><button id="sendButton" class="button" disabled>发送</button></form></div></div></section>
<section id="files" class="section"><div class="toolbar"><input id="search" placeholder="搜索文件名、类型或日期" oninput="renderFiles()"><button class="button secondary" onclick="loadFiles()">刷新</button></div><div class="panel table-wrap"><table><thead><tr><th>文件</th><th>大小</th><th>日期</th><th>上传时间</th><th>操作</th></tr></thead><tbody id="fileRows"></tbody></table><div id="fileEmpty" class="empty hidden">暂无普通文件</div></div></section>
<section id="audio" class="section"><div class="toolbar"><input id="audioSearch" placeholder="搜索语音或日期" oninput="renderAudio()"><button class="button secondary" onclick="loadAudio()">刷新</button></div><div class="panel table-wrap"><table><thead><tr><th>语音</th><th>大小</th><th>日期</th><th>上传时间</th><th>操作</th></tr></thead><tbody id="audioRows"></tbody></table><div id="audioEmpty" class="empty hidden">暂无语音文件</div></div></section>
<section id="account" class="section"><div class="panel account-card"><h2>账号安全</h2><div class="notice">修改后，App 和其他浏览器中的旧登录状态会立即失效，需要使用新账号密码重新登录。</div><form onsubmit="changeAccount(event)"><label class="field"><span>当前密码</span><input id="currentPassword" type="password" required></label><label class="field"><span>新账号</span><input id="newUsername" required minlength="3" maxlength="48"></label><label class="field"><span>新密码</span><input id="newPassword" type="password" required minlength="8"></label><label class="field"><span>确认新密码</span><input id="confirmPassword" type="password" required minlength="8"></label><button class="button">保存账号设置</button><div id="accountMessage" class="success"></div></form></div></section>
<section id="system" class="section"><div class="panel"><div class="panel-title">系统状态</div><div class="status-list"><div class="status-row"><span>网关版本</span><span id="gatewayVersion">—</span></div><div class="status-row"><span>Hermes 版本</span><span id="hermesVersion">—</span></div><div class="status-row"><span>登录有效期</span><span>30 天</span></div><div class="status-row"><span>服务入口</span><span id="systemEntry"></span></div><div class="status-row"><span>服务模式</span><span>Nexus 网关直连 8787</span></div></div></div></section>
</main></section>
<script>
let token=localStorage.getItem('nexus_token')||'',files=[],audioFiles=[],sessions=[],activeSessionId=null,streaming=false;const auth=()=>({'Authorization':'Bearer '+token});const titles={overview:['概览','Nexus运行概况'],chat:['网页聊天','查看 Hermes 会话并直接与Nexus对话'],files:['文件管理','按日期管理普通文件'],audio:['语音管理','按日期管理语音文件'],account:['账号安全','修改网页端和 App 共用的登录账号'],system:['系统状态','网关、Hermes 与统一入口状态']};
async function signIn(e){e.preventDefault();loginError.textContent='';const r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:username.value,password:password.value})});if(!r.ok){loginError.textContent='账号或密码错误';return}const x=await r.json();token=x.access_token;localStorage.setItem('nexus_token',token);localStorage.setItem('nexus_username',x.username);showApp()}
function showApp(){loginPage.classList.add('hidden');appPage.classList.remove('hidden');entryAddress.textContent=location.origin;systemEntry.textContent=location.origin;newUsername.value=localStorage.getItem('nexus_username')||'';loadAll()}
function logout(){localStorage.removeItem('nexus_token');token='';location.reload()}
function showPage(name){document.querySelectorAll('.section').forEach(x=>x.classList.toggle('active',x.id===name));document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===name));pageTitle.textContent=titles[name][0];pageDesc.textContent=titles[name][1];if(name==='chat')loadSessions();if(name==='files')loadFiles();if(name==='audio')loadAudio();if(name==='system')loadHealth()}
async function api(url,opt={}){opt.headers={...(opt.headers||{}),...auth()};const r=await fetch(url,opt);if(r.status===401){logout();throw Error('登录已失效')}return r}
async function loadAll(){await Promise.all([loadOverview(),loadSessions(),loadFiles(),loadAudio(),loadHealth()])}
async function loadOverview(){const r=await api('/api/admin/overview');const x=await r.json();metricSessions.textContent=x.session_count;metricFiles.textContent=x.file_count;metricAudio.textContent=x.audio_count;metricBytes.textContent=size(x.file_bytes+x.audio_bytes);gatewayVersion.textContent=x.gateway_version;gatewayStatus.textContent='正常';hermesStatus.textContent=x.status==='ok'?'正常':'连接异常'}
async function loadHealth(){const r=await fetch('/health');const x=await r.json();gatewayVersion.textContent=x.version||'—';hermesVersion.textContent=x.upstream?.version||'—';gatewayStatus.textContent=x.status==='ok'?'正常':'异常';hermesStatus.textContent=x.upstream?.status==='ok'?'正常':'异常'}
async function loadSessions(){const r=await api('/api/sessions');sessions=(await r.json()).data||[];renderSessions();if(activeSessionId&&!sessions.some(s=>s.id===activeSessionId)){activeSessionId=null}}
function renderSessions(){const q=(sessionSearch?.value||'').toLowerCase();const view=sessions.filter(s=>((s.title||'新对话')+' '+(s.source||'')).toLowerCase().includes(q));sessionRows.innerHTML=view.map(s=>`<div class="conversation ${s.id===activeSessionId?'active':''}" onclick="openSession('${escAttr(s.id)}')"><b>${esc(s.title||'新对话')}</b><span class="muted">${esc(s.source||'未知渠道')} · ${s.message_count||0} 条</span></div>`).join('')||'<div class="empty">暂无对话</div>'}
async function openSession(id){activeSessionId=id;renderSessions();const s=sessions.find(x=>x.id===id);chatTitle.textContent=s?.title||'新对话';chatInput.disabled=false;sendButton.disabled=false;messages.innerHTML='<div class="empty">正在加载…</div>';const r=await api('/api/sessions/'+encodeURIComponent(id)+'/messages');const data=(await r.json()).data||[];messages.innerHTML=data.filter(m=>m.role==='user'||m.role==='assistant').map(m=>`<div class="message ${m.role==='user'?'user':'assistant'}">${esc(messageText(m.content))}</div>`).join('')||'<div class="empty">这个对话还没有消息</div>';messages.scrollTop=messages.scrollHeight}
function messageText(content){if(typeof content==='string')return content;if(Array.isArray(content))return content.filter(x=>x&&['text','input_text'].includes(x.type)).map(x=>x.text||'').join('\n');return ''}
async function sendChat(e){e.preventDefault();const text=chatInput.value.trim();if(!text||!activeSessionId||streaming)return;chatInput.value='';streaming=true;sendButton.disabled=true;messages.insertAdjacentHTML('beforeend',`<div class="message user">${esc(text)}</div><div id="streamBubble" class="message assistant">思考中…</div>`);messages.scrollTop=messages.scrollHeight;try{const r=await api('/api/sessions/'+encodeURIComponent(activeSessionId)+'/chat/stream',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text})});if(!r.ok)throw Error('发送失败');const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='',answer='';while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const blocks=buffer.split('\n\n');buffer=blocks.pop()||'';for(const block of blocks){const event=(block.match(/^event:\s*(.+)$/m)||[])[1]||'';const raw=(block.match(/^data:\s*(.+)$/m)||[])[1];if(!raw)continue;let data;try{data=JSON.parse(raw)}catch{continue}if(event==='assistant.delta'||event==='message.delta'||event==='response.output_text.delta'){answer+=data.delta||data.text||'';streamBubble.textContent=answer||'思考中…'}else if(event.includes('tool')&&event.includes('start'))streamBubble.textContent='正在使用工具…'}}if(!answer)streamBubble.textContent='已完成';await loadSessions()}catch(err){streamBubble.textContent='发送失败，请重试';chatInput.value=text}finally{streaming=false;sendButton.disabled=false;messages.scrollTop=messages.scrollHeight}}
async function loadFiles(){const r=await api('/api/admin/files');files=(await r.json()).data||[];renderFiles()}async function loadAudio(){const r=await api('/api/admin/audio');audioFiles=(await r.json()).data||[];renderAudio()}
function renderFiles(){const q=search.value.toLowerCase();const view=files.filter(f=>(f.name+' '+f.mime_type+' '+f.date).toLowerCase().includes(q));fileRows.innerHTML=view.map(f=>row(f,'removeFile')).join('');fileEmpty.classList.toggle('hidden',view.length!==0)}function renderAudio(){const q=audioSearch.value.toLowerCase();const view=audioFiles.filter(f=>(f.name+' '+f.date).toLowerCase().includes(q));audioRows.innerHTML=view.map(f=>row(f,'removeAudio')).join('');audioEmpty.classList.toggle('hidden',view.length!==0)}
function row(f,remove){return`<tr><td><b>${esc(f.name)}</b></td><td>${size(f.size)}</td><td>${esc(f.date||'—')}</td><td>${new Date(f.created_at*1000).toLocaleString()}</td><td><button class="button secondary" onclick="downloadFile('${f.id}','${encodeURIComponent(f.name)}')">下载</button> <button class="button danger" onclick="${remove}('${f.id}')">删除</button></td></tr>`}
async function downloadFile(id,name){const r=await api('/api/files/'+id);const a=document.createElement('a');a.href=URL.createObjectURL(await r.blob());a.download=decodeURIComponent(name);a.click();URL.revokeObjectURL(a.href)}async function removeFile(id){if(confirm('确定删除这个文件？')){await api('/api/files/'+id,{method:'DELETE'});loadFiles();loadOverview()}}async function removeAudio(id){if(confirm('确定删除这条语音？')){await api('/api/files/'+id,{method:'DELETE'});loadAudio();loadOverview()}}
async function changeAccount(e){e.preventDefault();accountMessage.textContent='';if(newPassword.value!==confirmPassword.value){accountMessage.textContent='两次输入的新密码不一致';return}const r=await api('/api/admin/account',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({current_password:currentPassword.value,username:newUsername.value,password:newPassword.value})});const x=await r.json();if(!r.ok){accountMessage.textContent=x.error?.message||'修改失败';return}token=x.access_token;localStorage.setItem('nexus_token',token);localStorage.setItem('nexus_username',x.username);currentPassword.value='';newPassword.value='';confirmPassword.value='';accountMessage.textContent='修改成功，其他设备需要重新登录'}
function size(n){if(n>=1048576)return(n/1048576).toFixed(1)+' MB';if(n>=1024)return(n/1024).toFixed(1)+' KB';return(n||0)+' B'}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function escAttr(s){return String(s).replace(/'/g,'&#39;')}
if(token)showApp();
</script></body></html>'''
